    const {drafts,unit:storedUnit}=draftsFromInvoice(saved),customer={id:selectedCustomer.id,code:selectedCustomer.code,name:selectedCustomer.name,phone:selectedCustomer.phone};
    setCurrentCustomer(customer);setOrderReturnView("customers");setThobeDrafts(drafts);setCurrentThobe(0);applyThobe(drafts[0]);setUnit(storedUnit);setWeight(saved.weight);setTotalThobes(String(drafts.length));
    const usage=Object.fromEntries(Array.from(new Set(drafts.map(item=>item.fabricItemId).filter((id):id is number=>id!==null))).map(id=>[id,drafts.filter(item=>item.fabricItemId===id).reduce((sum,item)=>sum+numericValue(item.fabricMeters),0)]));
    if(duplicate){setDeliveryDate(deliveryAfter(5));setDayCount("5");setTotalPrice("");setPaidAmount("");setDiscount("");setPaymentMethod("كاش");setInvoice(null);setSavedFabricUsage({});setOrderLocked(false);setOrderMessage(`تم نسخ مقاسات الفاتورة ${sequenceNumber(saved.invoiceNumber)} إلى فاتورة جديدة`)}
